verus! {
    use verus::prelude::*;

    ///////////////////////////////////////////////////////////////////////////
    // reverse
    //
    // Given a mutable Vec<u64>, reverse it in place without allocating
    // any new array.  On return, for every index i < n, we guarantee
    // v[i] == old(v)[n-1-i].
    ///////////////////////////////////////////////////////////////////////////
    pub fn reverse(v: &mut Vec<u64>)
        ensures
            // The length is preserved (this is automatically true for Vec.swap,
            // but we state it for clarity).
            v.len() == old(v@).len() &&
            // For each valid index k, the element at k is the old element
            // at position len-1-k.
            forall |k: usize| (k < v@.len()) ==>
                v@[k] == old(v@)[v@.len() - 1 - k]
    {
        let n: usize = v.len();
        // Capture the original contents of v for our specification.
        ghost let old_v: Seq<u64> = v@;

        // Two indices: i scans from 0 upwards, j from n-1 downwards.
        let mut i: usize = 0;
        let mut j: usize = if n == 0 { 0 } else { n - 1 };

        // Loop until i meets or passes j.
        while i < j
            invariant
                // Bounds invariant
                i <= j + 1 &&
                j < n &&
                i <= n &&
                // The prefix [0, i) is already fixed:
                // v[k] == old_v[n-1-k] for all k < i.
                forall |k: usize| (k < i) ==> v@[k] == old_v[n - 1 - k] &&
                // The suffix (j, n) is already fixed:
                // v[k] == old_v[n-1-k] for all k > j.
                forall |k: usize| ((j + 1) <= k && k < n) ==> v@[k] == old_v[n - 1 - k]
            decreases j - i
        {
            // Swap the two “mirrored” elements.
            v.swap(i, j);

            // Grow the fixed prefix and shrink the fixed suffix.
            i += 1;
            j -= 1;
        }

        // At loop exit, i >= j.  Combined with the invariants,
        // every position is now fixed.  We assert the full
        // reversal property one more time to discharge the
        // postcondition.
        assert(forall |k: usize| (k < n) ==> v@[k] == old_v[n - 1 - k]);
    }
}